  \draw[->] (1.15,-1.15) -- (0.18,-0.18);
  \draw[->] (-0.18,0.18) -- (-1.15,1.15);
  \draw[->,line width=1.2pt] (-1.15,-1.15) -- (1.15,1.15);
  \node at (0.92,-0.82) {$x$};
  \node at (-0.82,-0.82) {$y$};
  \node at (-0.82,0.92) {$z$};
  \node at (0.35,0.35) {$z=x*y$};
\end{tikzpicture}
```

